B.b4G=s(["    CREATE TABLE IF NOT EXISTS companies (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      name TEXT NOT NULL,\n      name_ar TEXT NOT NULL,\n      tax_number TEXT,\n      commercial_registry TEXT,\n      phone TEXT,\n      address TEXT,\n      currency TEXT NOT NULL DEFAULT 'EGP',\n      logo_path TEXT\n    );\n    ","    CREATE TABLE IF NOT EXISTS fiscal_years (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      code TEXT NOT NULL UNIQUE,\n      name TEXT NOT NULL,\n      start_date TEXT NOT NULL,\n      end_date TEXT NOT NULL,\n      is_closed INTEGER NOT NULL DEFAULT 0\n    );\n    ","    CREATE TABLE IF NOT EXISTS accounting_periods (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      fiscal_year_id INTEGER NOT NULL,\n      period_number INTEGER NOT NULL,\n      name TEXT NOT NULL,\n      start_date TEXT NOT NULL,\n      end_date TEXT NOT NULL,\n      is_closed INTEGER NOT NULL DEFAULT 0,\n      closed_at TEXT,\n      closed_by TEXT,\n      FOREIGN KEY (fiscal_year_id) REFERENCES fiscal_years (id) ON DELETE CASCADE\n    );\n    ","    CREATE TABLE IF NOT EXISTS account_groups (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      code TEXT NOT NULL UNIQUE,\n      name TEXT NOT NULL,\n      name_ar TEXT NOT NULL,\n      parent_id INTEGER,\n      category TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS accounts (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      code TEXT NOT NULL UNIQUE,\n      name TEXT NOT NULL,\n      name_ar TEXT NOT NULL,\n      group_id INTEGER,\n      parent_id INTEGER,\n      account_type TEXT NOT NULL,\n      sub_type TEXT NOT NULL,\n      normal_balance TEXT NOT NULL DEFAULT 'debit',\n      is_active INTEGER NOT NULL DEFAULT 1,\n      requires_project INTEGER NOT NULL DEFAULT 0,\n      requires_analytical INTEGER NOT NULL DEFAULT 0,\n      notes TEXT,\n      level INTEGER NOT NULL DEFAULT 1,\n      FOREIGN KEY (group_id) REFERENCES account_groups (id) ON DELETE SET NULL,\n      FOREIGN KEY (parent_id) REFERENCES accounts (id) ON DELETE SET NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS projects (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      code TEXT NOT NULL UNIQUE,\n      name TEXT NOT NULL,\n      client TEXT,\n      start_date TEXT,\n      expected_end_date TEXT,\n      actual_end_date TEXT,\n      status TEXT NOT NULL DEFAULT 'active',\n      budget REAL NOT NULL DEFAULT 0.0,\n      notes TEXT\n    );\n    ","    CREATE TABLE IF NOT EXISTS analytical_items (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      code TEXT NOT NULL UNIQUE,\n      name TEXT NOT NULL,\n      category TEXT NOT NULL DEFAULT '\u0639\u0627\u0645',\n      is_active INTEGER NOT NULL DEFAULT 1,\n      notes TEXT\n    );\n    ","    CREATE TABLE IF NOT EXISTS units (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      code TEXT NOT NULL UNIQUE,\n      name TEXT NOT NULL,\n      symbol TEXT,\n      is_active INTEGER NOT NULL DEFAULT 1\n    );\n    ","    CREATE TABLE IF NOT EXISTS contractors (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      code TEXT NOT NULL UNIQUE,\n      name TEXT NOT NULL,\n      phone TEXT,\n      address TEXT,\n      tax_number TEXT,\n      project_id INTEGER,\n      opening_balance REAL NOT NULL DEFAULT 0.0,\n      notes TEXT,\n      is_active INTEGER NOT NULL DEFAULT 1,\n      FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE SET NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS suppliers (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      code TEXT NOT NULL UNIQUE,\n      name TEXT NOT NULL,\n      phone TEXT,\n      address TEXT,\n      tax_number TEXT,\n      opening_balance REAL NOT NULL DEFAULT 0.0,\n      notes TEXT,\n      is_active INTEGER NOT NULL DEFAULT 1\n    );\n    ","    CREATE TABLE IF NOT EXISTS customers (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      code TEXT NOT NULL UNIQUE,\n      name TEXT NOT NULL,\n      phone TEXT,\n      address TEXT,\n      tax_number TEXT,\n      opening_balance REAL NOT NULL DEFAULT 0.0,\n      notes TEXT,\n      is_active INTEGER NOT NULL DEFAULT 1\n    );\n    ","    CREATE TABLE IF NOT EXISTS opening_balances (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      fiscal_year_id INTEGER NOT NULL,\n      account_id INTEGER NOT NULL,\n      project_id INTEGER,\n      analytical_item_id INTEGER,\n      debit REAL NOT NULL DEFAULT 0.0,\n      credit REAL NOT NULL DEFAULT 0.0,\n      description TEXT,\n      FOREIGN KEY (fiscal_year_id) REFERENCES fiscal_years (id) ON DELETE CASCADE,\n      FOREIGN KEY (account_id) REFERENCES accounts (id) ON DELETE RESTRICT,\n      FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE SET NULL,\n      FOREIGN KEY (analytical_item_id) REFERENCES analytical_items (id) ON DELETE SET NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS journal_entries (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      entry_number TEXT NOT NULL UNIQUE,\n      date TEXT NOT NULL,\n      description TEXT NOT NULL,\n      reference_number TEXT,\n      project_id INTEGER,\n      status TEXT NOT NULL DEFAULT 'draft',\n      created_by TEXT,\n      created_at TEXT NOT NULL,\n      posted_by TEXT,\n      posted_at TEXT,\n      cancelled_by TEXT,\n      cancelled_at TEXT,\n      cancel_reason TEXT,\n      FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE SET NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS journal_lines (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      journal_entry_id INTEGER NOT NULL,\n      line_number INTEGER NOT NULL,\n      account_id INTEGER NOT NULL,\n      project_id INTEGER,\n      analytical_item_id INTEGER,\n      unit_id INTEGER,\n      quantity REAL NOT NULL DEFAULT 0.0,\n      unit_price REAL NOT NULL DEFAULT 0.0,\n      debit REAL NOT NULL DEFAULT 0.0,\n      credit REAL NOT NULL DEFAULT 0.0,\n      contractor_id INTEGER,\n      supplier_id INTEGER,\n      customer_id INTEGER,\n      description TEXT,\n      reference TEXT,\n      FOREIGN KEY (journal_entry_id) REFERENCES journal_entries (id) ON DELETE CASCADE,\n      FOREIGN KEY (account_id) REFERENCES accounts (id) ON DELETE RESTRICT,\n      FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE SET NULL,\n      FOREIGN KEY (analytical_item_id) REFERENCES analytical_items (id) ON DELETE SET NULL,\n      FOREIGN KEY (unit_id) REFERENCES units (id) ON DELETE SET NULL,\n      FOREIGN KEY (contractor_id) REFERENCES contractors (id) ON DELETE SET NULL,\n      FOREIGN KEY (supplier_id) REFERENCES suppliers (id) ON DELETE SET NULL,\n      FOREIGN KEY (customer_id) REFERENCES customers (id) ON DELETE SET NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS roles (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      code TEXT NOT NULL UNIQUE,\n      name TEXT NOT NULL,\n      description TEXT,\n      is_system INTEGER NOT NULL DEFAULT 0\n    );\n    ","    CREATE TABLE IF NOT EXISTS permissions (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      role_id INTEGER NOT NULL,\n      permission_key TEXT NOT NULL,\n      is_granted INTEGER NOT NULL DEFAULT 1,\n      FOREIGN KEY (role_id) REFERENCES roles (id) ON DELETE CASCADE,\n      UNIQUE(role_id, permission_key)\n    );\n    ","    CREATE TABLE IF NOT EXISTS users (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      username TEXT NOT NULL UNIQUE,\n      full_name TEXT NOT NULL,\n      email TEXT,\n      password_hash TEXT NOT NULL,\n      role_id INTEGER NOT NULL,\n      is_active INTEGER NOT NULL DEFAULT 1,\n      last_login_at TEXT,\n      FOREIGN KEY (role_id) REFERENCES roles (id) ON DELETE RESTRICT\n    );\n    ","    CREATE TABLE IF NOT EXISTS audit_logs (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      user_id INTEGER,\n      username TEXT NOT NULL,\n      action TEXT NOT NULL,\n      record_type TEXT NOT NULL,\n      record_id TEXT,\n      details TEXT,\n      old_values TEXT,\n      new_values TEXT,\n      created_at TEXT NOT NULL\n    );\n    ","    CREATE TABLE IF NOT EXISTS attachments (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      record_type TEXT NOT NULL,\n      record_id INTEGER NOT NULL,\n      file_name TEXT NOT NULL,\n      file_path TEXT NOT NULL,\n      file_size INTEGER,\n      mime_type TEXT,\n      created_at TEXT NOT NULL\n    );\n    ","CREATE INDEX IF NOT EXISTS idx_journal_entries_date_status ON journal_entries(date, status);","CREATE INDEX IF NOT EXISTS idx_journal_entries_project ON journal_entries(project_id);","CREATE INDEX IF NOT EXISTS idx_journal_lines_entry ON journal_lines(journal_entry_id);","CREATE INDEX IF NOT EXISTS idx_journal_lines_account ON journal_lines(account_id);","CREATE INDEX IF NOT EXISTS idx_journal_lines_project ON journal_lines(project_id);","CREATE INDEX IF NOT EXISTS idx_journal_lines_contractor ON journal_lines(contractor_id);","CREATE INDEX IF NOT EXISTS idx_journal_lines_analytical ON journal_lines(analytical_item_id);","CREATE INDEX IF NOT EXISTS idx_accounts_code ON accounts(code);","CREATE INDEX IF NOT EXISTS idx_accounts_type ON accounts(account_type);","CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at);"],t.s)
